async function main() {
  let count = 0;
  for (const [id, data] of Object.entries(ENRICHMENT)) {
    await db.collection("problems").doc(id).update(data);
    count++;
    console.log("enriched:", id);
  }
  console.log(`\nDone. ${count} problems enriched.`);
  process.exit(0);
}
main().catch(e => { console.error(e); process.exit(1); });
